package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    attribute previousPressed : Boolean := false;
    attribute mode : Integer := 0;
    attribute yellowRemainingMs : Integer := 0;
    attribute redRemainingMs : Integer := 0;
    perform action tick {
      first start;
      then if ((io_0) and ((not previousPressed))) {
        first start;
        then assign mode := 1;
        then assign yellowRemainingMs := 1000;
        then assign redRemainingMs := 2000;
      }
      then if mode == 1 {
        first start;
        then assign yellowRemainingMs := yellowRemainingMs - 10;
        then if yellowRemainingMs - 10 <= 0 {
          first start;
          then assign mode := 2;
        }
      }
      then if mode == 2 {
        first start;
        then assign redRemainingMs := redRemainingMs - 10;
        then if redRemainingMs - 10 <= 0 {
          first start;
          then assign mode := 0;
        }
      }
      then assign previousPressed := io_0;
    }
    out attribute io_1 : Boolean = mode == 2;
    out attribute io_2 : Boolean = mode == 1;
    out attribute io_3 : Boolean = mode == 0;
  }
  part system : Controller;
}
